package com.aistock.prediction.explanation;
import com.aistock.prediction.verification.*;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class ExplanationMysqlTest {
 final VerificationDatabaseFixture f=new VerificationDatabaseFixture();final ObjectMapper m=new ObjectMapper();final Instant now=Instant.parse("2026-10-07T05:00:00Z");
 UUID user=UUID.randomUUID(),pred=UUID.randomUUID();
 ExplanationRepository repo(){f.jdbc.update("insert into forecast_request(prediction_id,user_id,operation_id,request_hash,model_id,instrument_id,horizon,state,model_json,snapshot_json,hidden,created_at,expires_at) values(?,?,?,?,?,'SH600030',5,'SUCCEEDED','{}','{}',true,?,?)",pred.toString(),user.toString(),UUID.randomUUID().toString(),"a".repeat(64),UUID.randomUUID().toString(),java.sql.Timestamp.from(now),java.sql.Timestamp.from(now.plusSeconds(90)));return new ExplanationRepository(f.jdbc,m);}
 ExplanationFacts.Facts facts(String hash){var context=m.createObjectNode().put("predictionId",pred.toString()).put("providerModel","model");context.putObject("facts").put("PRICE","100元");return new ExplanationFacts.Facts(context,Map.of("PRICE","100元"),hash.repeat(64));}
 @Test void replayCacheAndNewContextRetainOldResult(){var r=repo();var op=UUID.randomUUID();var a=r.claim(user,pred,op,facts("a"),now);assertTrue(a.execute());assertFalse(r.claim(user,pred,op,facts("b"),now).execute());var result=r.complete(op,m.createArrayNode(),null,now.plusSeconds(1));assertEquals("SUCCEEDED",result.path("state").asText());var replay=r.claim(user,pred,UUID.randomUUID(),facts("a"),now.plusSeconds(2));assertFalse(replay.execute());assertEquals(result.path("explanationId"),replay.receipt().path("explanationId"));var b=r.claim(user,pred,UUID.randomUUID(),facts("b"),now.plusSeconds(3));assertTrue(b.execute());r.complete(b.receipt().path("operationId").asText()==null?op:UUID.fromString(b.receipt().path("operationId").asText()),m.createArrayNode(),null,now.plusSeconds(4));assertEquals(2,f.jdbc.queryForObject("select count(*) from prediction_explanation",Integer.class));assertTrue(r.read(user,pred,"c".repeat(64),now).path("stale").asBoolean());}
 @Test void onlyOwnerAndLeaseCannotPublishLateOrRetryBlindly(){var r=repo();var op=UUID.randomUUID();r.claim(user,pred,op,facts("a"),now);assertThrows(RuntimeException.class,()->r.read(UUID.randomUUID(),pred,"a".repeat(64),now));assertThrows(RuntimeException.class,()->r.claim(user,pred,UUID.randomUUID(),facts("a"),now.plusSeconds(1)));assertEquals("FAILED",r.complete(op,m.createArrayNode(),null,now.plusSeconds(51)).path("state").asText());assertFalse(r.claim(user,pred,op,facts("a"),now.plusSeconds(52)).execute());assertEquals(0,f.jdbc.queryForObject("select count(*) from prediction_explanation",Integer.class));assertTrue(r.claim(user,pred,UUID.randomUUID(),facts("a"),now.plusSeconds(52)).execute());}
}
